mapper.select:
SELECT o.id, o.order_no AS orderNo, o.status, o.total_amount AS totalAmount, o.created_at AS createdAt, (SELECT COUNT(*) FROM sales_order_item i WHERE i.order_id = o.id) AS itemCount FROM sales_order o WHERE o.user_id = #{userId}
AND o.status = #{status}
AND o.order_no = #{orderNo}
ORDER BY o.created_at DESC, o.id DESC

mapper.update:
UPDATE sales_order
SET status = 'CANCELLED',
    cancelled_at = #{cancelledAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PENDING_PAYMENT'

UPDATE sales_order
SET status = 'SHIPPED',
    shipped_at = #{shippedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PAID'

UPDATE sales_order
SET status = 'COMPLETED',
    completed_at = #{completedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'SHIPPED'
